\begin{lemma}\label{lem:irred}
Let $S'$ be a system obtained from $S$ by first applying Rule~\ref{rule1} as long as possible and then Rule \ref{rulerank} as long as possible. Then $S'$ is irreducible.
\end{lemma}
\begin{proof}
Let $S^*$ denote the system obtained from $S$ by applying Rule~\ref{rule1} as long as possible. Without loss of generality, assume that $x_1\not\in \{x_{i_1},\ldots ,x_{i_t}\}$ (see the description of Rule \ref{rulerank}) and thus Rule \ref{rulerank} removes $x_1$ from $S^*$. To prove the lemma
it suffices to show that after $x_1$ removal no pair of equations has the same left hand side. Suppose that there is a pair of equations in $S^*$ which has the same left hand side after $x_1$ removal; let $\prod_{i \in I'} x_i =b'$
and $\prod_{i \in I''} x_i =b''$ be such equations and let $I'=I''\cup \{1\}$. Then the entries of the first column of $A$, $a^1$, corresponding to the pair of equations are 1 and 0, but in all the other columns of $A$ the entries corresponding to the the pair of equations are either 1,1 or 0,0. Thus, $a^1$ is independent from all the other columns of $A$, a contradiction.\qed

\begin{corollary}\label{cor1}
The problem {\sc MaxLin2-AA}[$k$] can be solved in time $2^{O(k\log k)}(nm)^{O(1)}$.
\end{corollary}
\begin{proof}
Let $\cal L$ be an instance of {\sc MaxLin2-AA}[$k$]. By Theorem \ref{thm:main}, in time $(nm)^{O(1)}$ either we solve
$\cal L$ or we obtain a kernel
with at most $O(k^2\log k)$ variables. In the second case, we can solve the reduced system (kernel) by the algorithm of
Theorem \ref{thm:ing1} in time
$[O(k^2\log k)]^{2k}[O(k^2\log k)m]^{O(1)}=2^{O(k\log k)}m^{O(1)}$. Thus, the total time is $2^{O(k\log k)}(nm)^{O(1)}.$
\qed \end{proof}

\begin{corollary}
The maximization problem {\sc Max-$r$-Lin2-AA} is in APX if restricted to $m=O(n)$ and the weight of each equation is bounded by a constant.
\end{corollary}
\begin{proof}
It follows from Theorem \ref{thLinAAkr} that the answer to {\sc Max-$r$-Lin2-AA}, as a decision problem, is {\sc Yes} as long as $2k\le \lfloor (n+r-1)/r\rfloor.$
This implies approximation ratio at most $W/(2\lfloor (n+r-1)/r\rfloor)$ which is bounded by a constant provided $m=O(n)$ and the weight of each equation is bounded by a constant (then $W=O(n)$).
\qed \end{proof}

\begin{theorem}\label{thm:PBB}
Let \begin{equation}\label{fourier} f(x)=\hat{f}(\emptyset) + \sum_{I\in {\cal F}}\hat{f}(I)\prod_{i\in I}x_i\end{equation} be a pseudo-boolean function of degree $r$. Then
\begin{equation}\label{LBpb1t}\max_x f(x)\ge \hat{f}(\emptyset) + \lfloor ({\rm rank} A +r -1)/r\rfloor \cdot \min \{|\hat{f}(I)|: I\in {\cal F}\},\end{equation} where $A$ is a $(0,1)$-matrix with entries $a_{ij}$ such that $a_{ij}=1$ if and only if term $j$ in (\ref{fourier}) contains $x_i.$ One can find an assignment of values to $x$ satisfying (\ref{LBpb1t}) in time $(n|{\cal F}|)^{O(1)}.$
\end{theorem}
\begin{proof}
By Remark \ref{PseudoBExcess} the function $f(x) - \hat{f}(\emptyset) =\sum_{I\in {\cal F}}\hat{f}(I)\prod_{i\in I}x_i$ is the excess over the system $\prod_{i\in I}x_i=b_I$, $I\in {\cal F}$, where $b_I=+1$ if $\hat{f}(I)>0$ and $b_I=-1$ if $\hat{f}(I)<0$, with weights $|\hat{f}(I)|.$ Clearly, Rule \ref{rule1} will not change the system.
Using Rule \ref{rulerank} we can replace the system by an equivalent one (by Lemma \ref{lem:SS'}) with ${\rm rank} A$ variables. By Lemma \ref{lem:irred}, the new system is irreducible and we can now apply Theorem \ref{lemYes}. By this theorem, Remark \ref{PseudoBExcess} and Remark \ref{rem:reals}, $\max_x f(x)\ge  \hat{f}(\emptyset)+k^*\min \{|\hat{f}(I)|: I\in {\cal F}\}$, where $k^*$ is the maximum value of $k$ satisfying ${\rm rank} A\ge (k-1)r+1$. It remains to observe that $k^*=\lfloor ({\rm rank} A +r -1)/r\rfloor$.
\qed \end{proof}

\begin{theorem}
Let $G=(V,E)$ be a connected graph with $n$ vertices and $m$ edges. Then $G$ contains a bipartite subgraph with at least $\frac{m}{2} + \frac{n-1}{4}$ edges. Such a subgraph can be found in polynomial time.
\end{theorem}
\begin{proof}
Let $V=\{v_1,v_2,\ldots , v_n\}$ and let $c:\ V\rightarrow \{-1,1\}$ be a 2-coloring of $G$. Observe that the maximum number of edges in a bipartite subgraph of $G$ equals the maximum number of properly colored edges (i.e.,
edges whose end-vertices received different colors) over all 2-colorings of $G$. For an edge $e=v_iv_j\in E$ consider the following function $f_e(x)=\frac{1}{2}(1-x_ix_j)$, where $x_i=c(v_i)$ and $x_j=c(v_j)$ and observe that $f_e(x)=1$ if $e$ is properly colored by $c$ and $f_e(x)=0,$ otherwise. Thus, $f(x)=\sum_{e\in E}f_e(x)$ is the number of properly colored edges for $c$.
We have $f(x)=\frac{m}{2}-\frac{1}{2}\sum_{e\in E}x_ix_j$. By Theorem \ref{thm:PBB}, $\max_x f(x)\ge m/2 + \lfloor ({\rm rank} A +2 -1)/2\rfloor/2.$ Observe that matrix $A$ in this bound is  an incidence matrix of $G$ and, thus, by Lemma \ref{lem:M} ${\rm rank} A = n-1$. Hence, $\max_x f(x)\ge \frac{m}{2} + \frac{1}{2}\lfloor \frac{n}{2} \rfloor \ge \frac{m}{2} + \frac{n-1}{4}$ as required.
\qed \end{proof}

